const current = objects.getAll('castle').find(c => c.definition.id === 'royal-bedroom-castle'); current.regenerate(10).then(seed => { if (seed !== null) { const castle = objects.getAll('castle').find(c => c.definition.id === 'royal-bedroom-castle');
const plan = castle.definition.buildPlan.metadata.runtime.residential;
const room = plan.rooms['royal-chamber'];
const bed = plan.furniture.find(i => i.roomId === 'royal-chamber' && i.role === 'royalBed');
const furniture = plan.furniture.filter(i => i.roomId === 'royal-chamber' && !i.supportId && !i.floorCovering);
const doors = plan.openings.filter(o => o.kind === 'door' && o.floorY === room.floorY);
const points = [];
for (let x = room.minX + 0.4; x <= room.maxX - 0.4; x += 0.2) {
  for (let z = room.minZ + 0.4; z <= room.maxZ - 0.4; z += 0.2) {
    const clearDoor = doors.every(o => Math.abs((o.axis === 'x' ? x : z)-o.coordinate) > 1.6 || Math.abs((o.axis === 'x' ? z : x)-o.center) > o.width/2+0.35);
    const clearSight = furniture.every(i => i === bed || [0.2,0.4,0.6,0.8].every(t => Math.abs(x+(bed.x-x)*t-i.x) > i.width*i.scale/2+0.1 || Math.abs(z+(bed.z-z)*t-i.z) > i.depth*i.scale/2+0.1));
    if (clearDoor && clearSight && furniture.every(i => Math.abs(x - i.x) > i.width * i.scale / 2 + 0.35 || Math.abs(z - i.z) > i.depth * i.scale / 2 + 0.35)) {
      points.push({x,z,distance:-Math.abs(Math.hypot(x-bed.x,z-bed.z)-2.5)});
    }
  }
}
points.sort((a,b) => b.distance-a.distance);
const point = points[0];
if (point) {
  const angle = plan.origin.yaw * Math.PI / 180;
  const hero = objects.getOne('hero');
  camera.setFirstPerson(false);
  hero.teleport({x:plan.origin.x+Math.cos(angle)*point.x+Math.sin(angle)*point.z,y:room.floorY+0.014,z:plan.origin.z-Math.sin(angle)*point.x+Math.cos(angle)*point.z});
  hero.firstPersonCameraEnabled = true;
  hero.firstPersonFacingYaw = plan.origin.yaw + Math.atan2(bed.x-point.x,bed.z-point.z)*180/Math.PI;
  camera.setFirstPerson(true);
} } });

